<?php
$requests=rows('SELECT r.*,CONCAT(u.first_name," ",u.last_name) resident_name,rr.read_at FROM document_requests r JOIN users u ON u.id=r.user_id LEFT JOIN admin_request_reads rr ON rr.request_id=r.id AND rr.admin_id=? ORDER BY r.created_at DESC,r.id DESC',[$admin['id']]);
?>
<div class="section-title"><h2>Submitted Requests Table</h2><?php action_form('read_reports'); ?><?php foreach($requests as $r): ?><input type="hidden" name="ids[]" value="<?= (int)$r['id'] ?>"><?php endforeach; ?><button class="button secondary">Mark All as Read</button></form></div>
<section class="panel table-scroll"><table><thead><tr><th>Request</th><th>Document</th><th>Resident</th><th>Status</th><th>Submitted</th><th>Read</th></tr></thead><tbody><?php foreach($requests as $r): ?><tr class="<?= $r['read_at']?'report-read':'report-unread' ?>"><td><?= e(request_id((int)$r['id'])) ?></td><td><?php action_form('read_report',(int)$r['id']); ?><button class="text-button"><?= e($r['document_name']) ?></button></form></td><td><?= e($r['resident_name']) ?></td><td><?= e(status_label($r['status'])) ?></td><td><?= e($r['created_at']) ?></td><td><?= $r['read_at']?'Read':'Unread' ?></td></tr><?php endforeach; ?></tbody></table><?php if(!$requests): ?><p class="empty">No submitted requests.</p><?php endif; ?></section>
<?php $open=query_input('open'); $r=null; foreach($requests as $item) if((string)$item['id']===$open && $item['read_at']) $r=$item; if($r): ?>
<section class="panel dashboard-actions"><h2><?= e($r['document_name'].' · '.request_id((int)$r['id'])) ?></h2><dl class="summary-details"><?php foreach(['resident_name'=>'Resident','description'=>'Description','purpose'=>'Purpose','additional_information'=>'Additional information','status'=>'Status','review_reason'=>'Review reason','payment_status'=>'Payment','payment_amount'=>'Amount (PHP)','pickup_date'=>'Pickup date','processing_date'=>'Processing date','pickup_option'=>'Pickup','delivery_option'=>'Delivery'] as $key=>$label): ?><dt><?= e($label) ?></dt><dd><?= nl2br(e($key==='status'?status_label($r[$key]):($r[$key]??'—'))) ?></dd><?php endforeach; ?></dl><div class="document-paper"><?= $r['document_content']?clean_document($r['document_content']):'<p>'.nl2br(e($r['description'])).'</p>' ?></div><a class="button primary" href="index.php?page=reports">OK</a></section><?php endif; ?>
